/// The two halves of a cloud run that are about ONE media file: the janitor,
/// which is the run's first act, and the round trip, which is everything
/// between "this media is not cached" and "its words are on disk".
///
/// They are here rather than in `CloudTranscriber.swift` because that file
/// holds the run's SHAPE — the janitor, the grouping, the classification, the
/// per-job derivation and the two closing throws — and a reader following
/// that shape does not need the header's twelve fields or the order of the
/// five calls in front of them. Both files are under the 400-line cap a new
/// file has (app/CLAUDE.md, road map 6 §5h).
extension CloudTranscriber {

    /// Why one media could not be sent, in a sentence with no prefix on it.
    ///
    /// `Transcriber.TranscribeError.failed` would wrap this in "The
    /// transcription failed: ", which is true of the run and not of the
    /// media, and the refusal has to name the FILE and the limit — road map
    /// 6 §5g puts the ten-hour refusal above the network for exactly that
    /// reason: it is knowable before a byte is extracted, let alone sent.
    enum MediaError: LocalizedError, Equatable {
        case tooLong(String)

        var errorDescription: String? {
            switch self {
            case .tooLong(let name):
                return "“\(name)” is longer than AssemblyAI's 10-hour limit for one file."
            }
        }
    }

    // MARK: - The janitor

    /// R6-4's first act: every cached transcript whose remote copy this app
    /// has not managed to delete gets its DELETE retried, best effort, on
    /// `deleteTimeout` each.
    ///
    /// A success rewrites that one flag and nothing else —
    /// `MediaTranscript.File`'s header is mutated and written back through
    /// the same door, so the served `words` bytes are spliced through
    /// untouched and the file is never re-serialised. A failure is REPORTED
    /// rather than swallowed, because R6-11 makes it mean something: the run
    /// will not fetch that media at all, since this file is the one record of
    /// the id still owed a delete.
    ///
    /// A repeat DELETE of an already-deleted transcript answers 200 (C0's
    /// q6), so a retry can never make things worse.
    ///
    /// **A Stop is heard BETWEEN items.** `cancel` is optional and defaulted
    /// so `retryDeletes()` still means what it always did, but a run that has
    /// one hands its token over: each DELETE has only `deleteTimeout` of its
    /// own, and a cache owing three of them against a server that answers
    /// nothing made a person wait out fifteen seconds of a Stop they had
    /// already pressed (the reader review, §10.13 R1·2). What is left
    /// unvisited is in NEITHER list — nothing was attempted for it — which is
    /// safe because the one caller throws `cancelled` on the next line. The
    /// one IN FLIGHT is bounded rather than cut: its DELETE reads the token
    /// as a Stop and ends `deleteAfterStop` after it, a cut one `failed` and
    /// so owed like any other — kept in its file and in `janitorFailed`
    /// (R6-19).
    func retryDeletes(cancel: Transcriber.CancelToken? = nil) -> (
        deleted: [UInt32], failed: [UInt32]
    ) {
        guard let client else { return ([], []) }
        var deleted: [UInt32] = []
        var failed: [UInt32] = []
        for row in MediaTranscript.undeleted(in: cacheDirectory) {
            if cancel?.isCancelled == true { break }
            switch client.delete(id: row.transcriptID, cancel: cancel) {
            case .failed:
                failed.append(row.media)
                continue
            // An id no request could be made from is in NEITHER list: saying
            // `deleted` would report a delete nothing sent and would write
            if client == nil { continue }
            guard let entry = media[id], let url = grouped[id]?.first?.source,
                let source = MediaImporter.CacheStamp.stamp(for: entry, url: url)
            else {
                unreadable.append(id)
                continue
            }
            let stamp = TranscriptStamp(source: source, options: options)
            stamps[id] = stamp
            if MediaTranscript.isCurrent(stamp, for: id, in: cacheDirectory), !refresh {
                cached.append(id)
            } else if report.janitorFailed.contains(id) {
                held.append(id)
            } else {
                toUpload.append(id)
            }
        }
        report.held = held
        // Held and cached media are NOT in the shares: neither costs a
        // second of work, and a slice for one would make the bar stall.
        let bar = CloudProgress(seconds: toUpload.map { ReelTime.seconds(media[$0]?.duration ?? 0) })

        var files: [UInt32: MediaTranscript.File] = [:]
        var cues: [CaptionLayout.Cue] = []
        var problems: [CaptionLayout.Problem] = []
        var clips: [UInt32] = []
        // Kept apart from `problems` for `Transcriber.transcribe`'s reason:
        // they decide WHICH refusal an empty run earns.
        var failures: [String] = []

        func refuse(_ id: UInt32, _ reason: String) {
            for job in grouped[id] ?? [] {
                problems.append(CaptionLayout.Problem(tag: "clip \(job.clip)", reason: reason))
                failures.append("clip \(job.clip): \(reason)")
            }
        }

        for id in order {
            if cancel.isCancelled { throw Transcriber.TranscribeError.cancelled }
            if let file = keylessFiles[id] {
                files[id] = file
            } else if unreadable.contains(id) {
                refuse(id, "its media file could not be read")
            } else if cached.contains(id) {
                if let file = MediaTranscript.read(for: id, in: cacheDirectory) {
                    files[id] = file
                    report.cached.append(id)
                } else {
                    refuse(id, "its cached transcript could not be read")
                }
            } else if held.contains(id) {
                // R6-11, the whole of it: no fetch, no write, one sentence
                // per clip, and the file left byte for byte.
                refuse(
                    id,
                    "AssemblyAI has not confirmed deleting its earlier transcript, so it was "
                        + "not uploaded again; the next run with an API key retries the delete")
            } else if let index = toUpload.firstIndex(of: id), let entry = media[id],
                let url = grouped[id]?.first?.source, let stamp = stamps[id]
            {
                do {
                    let answer = try fetch(
                        media: entry, url: url, stamp: stamp, options: options, cancel: cancel,
                    refuse(id, error.localizedDescription)
                }
            }

            // (4) Every job on this media, derived from the one transcript.
            guard let file = files[id] else { continue }
            for job in grouped[id] ?? [] {
                let words = MediaTranscript.captionWords(for: job, in: file)
                    .filter { $0.start < job.start + job.duration }
                cues.append(
                    contentsOf: CaptionPages.cues(
                        from: words, span: job.span, frame: frame, request: pages,
                        engine: .assemblyai, clip: job.clip, media: job.media))
                if words.isEmpty {
                    problems.append(
                        CaptionLayout.Problem(
                            tag: "clip \(job.clip)", reason: "no speech was recognised in it"))
                } else {
                    clips.append(job.clip)
                }
            }
        }

        if cancel.isCancelled { throw Transcriber.TranscribeError.cancelled }
        guard !cues.isEmpty else {
            // `Transcriber.transcribe`'s two closing throws, same rule: "no
            // speech was recognised" is a claim about the AUDIO, and making
            // it when the audio was never read would send somebody looking
            // for words that are on the timeline.
            guard failures.isEmpty else {
                throw Transcriber.TranscribeError.failed(
                    failures.prefix(3).joined(separator: "; "))
            }
            throw Transcriber.TranscribeError.nothingRecognized
        }
        publish(1, "")
        return Transcriber.Outcome(cues: cues, problems: problems, clips: clips)
    }
}
