import Foundation

// The importer's ladder, then whether the decoded text holds a timing line.
func ladder(_ data: Data) -> (String, String)? {
    for (name, encoding) in [
        ("utf8", String.Encoding.utf8), ("utf16", .utf16), ("cp1252", .windowsCP1252),
        ("latin1", .isoLatin1),
    ] {
        if let text = String(data: data, encoding: encoding) { return (name, text) }
    }
    return nil
}

func report(_ label: String, _ data: Data) {
    guard let (name, text) = ladder(data) else { print(label, "-> none"); return }
    print(label, "->", name, "timing line:", text.contains("-->"))
}

func file(_ word: String) -> String {
    "1\n00:00:01,000 --> 00:00:02,000\n\(word)\n\n"
}

// Every accented letter, at both byte parities.
var outcomes: [String: Int] = [:]
for scalar in 0xC0...0xFF {
    let letter = String(UnicodeScalar(scalar)!)
    for pad in ["", "x"] {
        let data = file(pad + letter + " text").data(using: .isoLatin1)!
        let name = ladder(data)?.0 ?? "none"
        let good = ladder(data)?.1.contains("-->") ?? false
        outcomes["\(name) timing=\(good)", default: 0] += 1
    }
}
print(outcomes)
report("ascii only", file("plain").data(using: .ascii)!)
report("utf8 accented", file("Caf\u{e9}").data(using: .utf8)!)
report("utf8 with BOM", Data([0xEF, 0xBB, 0xBF]) + file("Caf\u{e9}").data(using: .utf8)!)
report("utf16 with BOM", file("Caf\u{e9}").data(using: .utf16)!)
report("utf16 BE no BOM", file("Caf\u{e9}").data(using: .utf16BigEndian)!)
report("utf16 LE no BOM", file("Caf\u{e9}").data(using: .utf16LittleEndian)!)

